from itertools import product

# === Q8: Quaternion group ===
# Represent as {1, -1, i, -i, j, -j, k, -k} with multiplication rules
Q8_elems = ['1', '-1', 'i', '-i', 'j', '-j', 'k', '-k']

def q8_mul(a, b):
    # multiplication table for Q8
    table = {
        '1': {'1':'1','-1':'-1','i':'i','-i':'-i','j':'j','-j':'-j','k':'k','-k':'-k'},
        '-1':{'1':'-1','-1':'1','i':'-i','-i':'i','j':'-j','-j':'j','k':'-k','-k':'k'},
        'i': {'1':'i','-1':'-i','i':'-1','-i':'1','j':'k','-j':'-k','k':'-j','-k':'j'},
        '-i':{'1':'-i','-1':'i','i':'1','-i':'-1','j':'-k','-j':'k','k':'j','-k':'-j'},
        'j': {'1':'j','-1':'-j','i':'-k','-i':'k','j':'-1','-j':'1','k':'i','-k':'-i'},
        '-j':{'1':'-j','-1':'j','i':'k','-i':'-k','j':'1','-j':'-1','k':'-i','-k':'i'},
        'k': {'1':'k','-1':'-k','i':'j','-i':'-j','j':'-i','-j':'i','k':'-1','-k':'1'},
        '-k':{'1':'-k','-1':'k','i':'-j','-i':'j','j':'i','-j':'-i','k':'1','-k':'-1'},
    }
    return table[a][b]

def order_q8(g):
    cur = g
    for n in range(1, 9):
        if cur == '1':
            return n
        cur = q8_mul(cur, g)
    return None

print("=== Q8 element orders ===")
q8_orders = {}
for g in Q8_elems:
    o = order_q8(g)
    q8_orders[g] = o
    print(f"  {g}: order {o}")

# Count by order
from collections import Counter
q8_order_counts = Counter(q8_orders.values())
print(f"  Order distribution: {dict(q8_order_counts)}")

# Cyclic subgroups of order 4
print("\n=== Q8 cyclic subgroups of order 4 ===")
q8_cyclic4 = set()
for g in Q8_elems:
    if q8_orders[g] == 4:
        # generate subgroup
        sub = set()
        cur = '1'
        for _ in range(4):
            sub.add(cur)
            cur = q8_mul(cur, g)
        sub.add(cur)  # should be identity
        frozen = frozenset(sub)
        q8_cyclic4.add(frozen)
        print(f"  <{g}> = {sorted(sub)}")
print(f"  Number of cyclic subgroups of order 4: {len(q8_cyclic4)}")

# Elements of order 2
q8_order2 = [g for g in Q8_elems if q8_orders[g] == 2]
print(f"\n=== Q8 elements of order 2: {q8_order2} (count={len(q8_order2)}) ===")

# All subgroups and check normality
print("\n=== Q8 all subgroups ===")
# Generate all subgroups by taking cyclic closures
def generate_subgroup_q8(generators):
    sub = {'1'}
    changed = True
    while changed:
        changed = False
        for g in list(sub):
            for gen in generators:
                prod = q8_mul(g, gen)
                if prod not in sub:
                    sub.add(prod)
                    changed = True
                prod2 = q8_mul(gen, g)
                if prod2 not in sub:
                    sub.add(prod2)
                    changed = True
        # also add inverses
        for g in list(sub):
            for h in Q8_elems:
                if q8_mul(g, h) == '1' and h not in sub:
                    sub.add(h)
                    changed = True
    return sub

# Known subgroups of Q8
q8_subgroups = [
    {'1'},
    {'1', '-1'},
    {'1', '-1', 'i', '-i'},
    {'1', '-1', 'j', '-j'},
    {'1', '-1', 'k', '-k'},
    set(Q8_elems),
]

def is_normal_q8(sub):
    for g in Q8_elems:
        for h in sub:
            conj = q8_mul(q8_mul(g, h), g)  # g*h*g (since g^-1 might be g or -g)
            # need g*h*g^{-1}
            # find g^{-1}
            g_inv = None
            for x in Q8_elems:
                if q8_mul(g, x) == '1':
                    g_inv = x
                    break
            conj = q8_mul(q8_mul(g, h), g_inv)
            if conj not in sub:
                return False
    return True

print("  Subgroup -> Normal?")
for sub in q8_subgroups:
    print(f"    {sorted(sub)}: {is_normal_q8(sub)}")

# Center of Q8
print("\n=== Q8 center ===")
q8_center = []
for g in Q8_elems:
    if all(q8_mul(g, h) == q8_mul(h, g) for h in Q8_elems):
        q8_center.append(g)
print(f"  Z(Q8) = {q8_center}")

# Commutator subgroup
print("\n=== Q8 commutator subgroup ===")
q8_commutators = set()
for a in Q8_elems:
    for b in Q8_elems:
        # [a,b] = a*b*a^{-1}*b^{-1}
        a_inv = [x for x in Q8_elems if q8_mul(a,x)=='1'][0]
        b_inv = [x for x in Q8_elems if q8_mul(b,x)=='1'][0]
        comm = q8_mul(q8_mul(q8_mul(a, b), a_inv), b_inv)
        q8_commutators.add(comm)
print(f"  [Q8,Q8] = {sorted(q8_commutators)}")

print("\n" + "="*60)

# === D4: Dihedral group of order 8 ===
# Elements: (rotation_index, reflection_flag) where rotation is 0-3
# e=(0,0), r=(1,0), r2=(2,0), r3=(3,0), s=(0,1), sr=(1,1), sr2=(2,1), sr3=(3,1)
D4_elems = [(r, f) for r in range(4) for f in range(2)]

def d4_mul(a, b):
    ra, fa = a
    rb, fb = b
    # (r^a s^f)(r^b s^g) = r^a s^f r^b s^g
    # if f=0: r^(a+b)
    # if f=1: r^a s r^b s^g = r^a r^(-b) s s^g = r^(a-b) s^(1+g)
    if fa == 0:
        return ((ra + rb) % 4, fb)
    else:
        return ((ra - rb) % 4, (1 + fb) % 2)

def d4_inv(a):
    ra, fa = a
    if fa == 0:
        return ((-ra) % 4, 0)
    else:
        return (ra, 1)  # s is its own inverse, sr * sr = e? Let's check: (r,s)(r,s) = r*s*r*s = r*r^{-1}*s*s = e. Yes.

def order_d4(g):
    cur = (0, 0)
    for n in range(1, 9):
        cur = d4_mul(cur, g)
        if cur == (0, 0):
            return n
    return None

print("=== D4 element orders ===")
d4_orders = {}
d4_names = {}
for g in D4_elems:
    r, f = g
    if f == 0:
        name = ['e','r','r2','r3'][r]
    else:
        name = ['s','sr','sr2','sr3'][r]
    d4_names[g] = name
    o = order_d4(g)
    d4_orders[g] = o
    print(f"  {name} {g}: order {o}")

d4_order_counts = Counter(d4_orders.values())
print(f"  Order distribution: {dict(d4_order_counts)}")

# Elements of order 2
d4_order2 = [d4_names[g] for g in D4_elems if d4_orders[g] == 2]
print(f"\n=== D4 elements of order 2: {d4_order2} (count={len(d4_order2)}) ===")

# Cyclic subgroups of order 4
print("\n=== D4 cyclic subgroups of order 4 ===")
d4_cyclic4 = set()
for g in D4_elems:
    if d4_orders[g] == 4:
        sub = set()
        cur = (0, 0)
        for _ in range(5):
            sub.add(cur)
            cur = d4_mul(cur, g)
        frozen = frozenset(sub)
        d4_cyclic4.add(frozen)
        print(f"  <{d4_names[g]}> = {[d4_names[x] for x in sorted(sub)]}")
print(f"  Number of cyclic subgroups of order 4: {len(d4_cyclic4)}")

# All subgroups of D4
print("\n=== D4 all subgroups ===")
def generate_subgroup_d4(generators):
    sub = {(0,0)}
    changed = True
    while changed:
        changed = False
        for g in list(sub):
            for gen in generators:
                for prod in [d4_mul(g, gen), d4_mul(gen, g)]:
                    if prod not in sub:
                        sub.add(prod)
                        changed = True
        for g in list(sub):
            inv = d4_inv(g)
            if inv not in sub:
                sub.add(inv)
                changed = True
    return sub

# Enumerate subgroups by trying all subsets as generators (brute force)
all_subs_d4 = set()
for r in range(1, 9):
    from itertools import combinations
    for combo in combinations(D4_elems, r):
        sub = generate_subgroup_d4(list(combo))
        all_subs_d4.add(frozenset(sub))

def is_normal_d4(sub_set):
    for g in D4_elems:
        g_inv = d4_inv(g)
        for h in sub_set:
            conj = d4_mul(d4_mul(g, h), g_inv)
            if conj not in sub_set:
                return False
    return True

print("  Subgroup -> Normal?")
d4_all_normal = True
d4_has_nonnormal = False
for sub in sorted(all_subs_d4, key=lambda s: (len(s), sorted(s))):
    names = sorted([d4_names[x] for x in sub])
    normal = is_normal_d4(sub)
    if not normal:
        d4_has_nonnormal = True
    print(f"    {names}: normal={normal}")

print(f"\n  D4 has non-normal subgroups: {d4_has_nonnormal}")

# Center of D4
print("\n=== D4 center ===")
d4_center = []
for g in D4_elems:
    if all(d4_mul(g, h) == d4_mul(h, g) for h in D4_elems):
        d4_center.append(d4_names[g])
print(f"  Z(D4) = {d4_center}")

# Commutator subgroup
print("\n=== D4 commutator subgroup ===")
d4_commutators = set()
for a in D4_elems:
    for b in D4_elems:
        a_inv = d4_inv(a)
        b_inv = d4_inv(b)
        comm = d4_mul(d4_mul(d4_mul(a, b), a_inv), b_inv)
        d4_commutators.add(comm)
print(f"  [D4,D4] = {sorted([d4_names[x] for x in d4_commutators])}")

print("\n" + "="*60)
print("=== SUMMARY OF INVARIANTS ===")
print(f"Elements of order 2:  Q8={len(q8_order2)},  D4={len(d4_order2)}")
print(f"Cyclic subgroups of order 4:  Q8={len(q8_cyclic4)},  D4={len(d4_cyclic4)}")
print(f"All subgroups normal:  Q8=True,  D4={not d4_has_nonnormal}")
print(f"Center:  Q8={q8_center},  D4={d4_center}")
print(f"Commutator subgroup:  Q8={sorted(q8_commutators)},  D4={sorted([d4_names[x] for x in d4_commutators])}")
